/** @typedef {import('./index.js').PermsModule} PermsModule */
/**
 * Request a specific permission string to be granted. Note that some
 * permission strings are not supported and will be denied silently.
 *
 * @this {PermsModule}
 * @param {string} permission - The permission string to request.
 * @returns {Promise<boolean>} `true` if the permission was granted.
 */
export function request(this: import("./index.js").PermsModule, permission: string): Promise<boolean>;
/**
 * @deprecated Use {@link request} instead.
 * @this {PermsModule}
 * @param {...unknown} args
 * @returns {Promise<boolean>}
 */
export function requestPermission(this: import("./index.js").PermsModule, ...args: unknown[]): Promise<boolean>;
/**
 * Request to see the user's email. If already granted, the user is not
 * prompted and their email is returned.
 *
 * @this {PermsModule}
 * @returns {Promise<string | null | undefined>} The email if granted, `null`
 * if granted but no email is on file, or `undefined` if access is denied.
 */
export function requestEmail(this: import("./index.js").PermsModule): Promise<string | null | undefined>;
/**
 * Request read access to the user's apps.
 * @this {PermsModule}
 * @returns {Promise<boolean>}
 */
export function requestReadApps(this: import("./index.js").PermsModule): Promise<boolean>;
/**
 * Request write (manage) access to the user's apps.
 * @this {PermsModule}
 * @returns {Promise<boolean>}
 */
export function requestManageApps(this: import("./index.js").PermsModule): Promise<boolean>;
/**
 * Request read access to the user's subdomains.
 * @this {PermsModule}
 * @returns {Promise<boolean>}
 */
export function requestReadSubdomains(this: import("./index.js").PermsModule): Promise<boolean>;
/**
 * Request write (manage) access to the user's subdomains.
 * @this {PermsModule}
 * @returns {Promise<boolean>}
 */
export function requestManageSubdomains(this: import("./index.js").PermsModule): Promise<boolean>;
export type PermsModule = import("./index.js").PermsModule;
